// This file is generated by AI.

// 配音工作流设置持久化 (localStorage)。
//
// 与 `lib/settings.ts` 分开存放: 配音配置体量较大且互相独立,
// 混在一起会让任何一处改动的读写都搬运全部数据。

import type { LaunchConfig } from '../commands/voice';
import { DEFAULT_VOICE_DEFAULTS, type VoiceDefaults } from './types';

export interface VoiceSettings {
  /** 启动配置 (含整合包路径与启动方式); null 表示尚未配置 */
  launch: LaunchConfig | null;
  /** 默认推理配置 */
  defaults: VoiceDefaults;
  /** 测试模式采样步数 (允许用户在 4/8 之间调整) */
  testSampleSteps: number;
}

const STORAGE_KEY = 'webgal-ink.voice';

export const defaultVoiceSettings: VoiceSettings = {
  launch: null,
  defaults: { ...DEFAULT_VOICE_DEFAULTS },
  testSampleSteps: 4,
};

export function loadVoiceSettings(): VoiceSettings {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...defaultVoiceSettings, defaults: { ...defaultVoiceSettings.defaults } };
    const parsed = JSON.parse(raw) as Partial<VoiceSettings>;
    return {
      launch: parsed.launch ?? null,
      defaults: { ...defaultVoiceSettings.defaults, ...(parsed.defaults ?? {}) },
      testSampleSteps: parsed.testSampleSteps ?? defaultVoiceSettings.testSampleSteps,
    };
  } catch {
    return { ...defaultVoiceSettings, defaults: { ...defaultVoiceSettings.defaults } };
  }
}

export function saveVoiceSettings(settings: VoiceSettings): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    // 存储不可用时静默忽略
  }
}
